examples:
```tsx
import { SegmentedControl } from '@/lib/designsystem';

function MyComponent() {
  const [view, setView] = useState('day');

  return (
    <SegmentedControl
      id="calendar-view"
      options={[
        { value: 'day', label: 'Day' },
        { value: 'week', label: 'Week' },
        { value: 'month', label: 'Month' }
      ]}
      value={view}
      onChange={setView}
      label="Calendar View"
    />
  );
}
```

